#!/bin/sh
# Generated by deploy/generate.sh from deploy/config.env, don't edit.
#
# certbot runs this after renewing the certificate, from
# /etc/letsencrypt/renewal-hooks/deploy where deploy/server.sh installs it.
# nginx reads the certificate from /etc/nginx/kite-tls.
set -e
install -m 600 "$RENEWED_LINEAGE/fullchain.pem" "$RENEWED_LINEAGE/privkey.pem" /etc/nginx/kite-tls/
systemctl reload nginx
